function drawEnemy(e){let[X,Y]=tileXY(e.x,e.y),t=p.tile,a=ANIMALS[e.kind]||ANIMALS.boar,now=performance.now();if(e.attackUntil>now){let pulse=Math.sin((e.attackUntil-now)/230*Math.PI),dx=p.px-e.x,dy=p.py-e.y;X+=dx*t*.22*pulse;Y+=dy*t*.22*pulse}if(e.hit&&Math.floor(now/45)%2){X+=Math.random()*4-2;Y+=Math.random()*4-2}if(a.tier>=4){ctx.strokeStyle=a.tier===5?'#ff9f43':'#d9b46c';ctx.lineWidth=2;ctx.strokeRect(X+t*.1,Y+t*.17,t*.8,t*.68)}ctx.fillStyle=e.hit?'#f4d6b0':a.color;ctx.fillRect(X+t*.18,Y+t*.4,t*.64,t*.34);ctx.fillRect(X+t*.56,Y+t*.23,t*.31,t*.3);ctx.fillStyle='#211512';ctx.fillRect(X+t*.7,Y+t*.31,3,3);ctx.fillStyle='#39201b';ctx.fillRect(X+t*.16,Y+t*.12,t*.58,4);ctx.fillStyle='#66ad63';ctx.fillRect(X+t*.16,Y+t*.12,t*.58*Math.max(0,e.hp)/(e.maxHp||50),4);ctx.font=`bold ${Math.max(7,t*.18)}px sans-serif`;ctx.textAlign='center';ctx.fillStyle=a.tier>=4?'#ffd27a':'#d8dfd8';ctx.fillText(a.name,X+t*.5,Y+t*.94)}
function drawPlayer(){let[X,Y]=tileXY(p.px,p.py),t=p.tile,b=p.path.length?Math.sin(time/80)*2:0,now=performance.now(),swing=0,working=playerWorkUntil>now;if(playerAttackUntil>now&&playerAttackTarget){let pulse=Math.sin((playerAttackUntil-now)/260*Math.PI),dx=playerAttackTarget.x-p.px,dy=playerAttackTarget.y-p.py;X+=dx*t*.2*pulse;Y+=dy*t*.2*pulse;swing=pulse}if(working){let pulse=Math.sin((playerWorkUntil-now)/90*Math.PI);Y+=Math.abs(pulse)*3}if(playerHitUntil>now){X+=Math.random()*5-2.5;Y+=Math.random()*5-2.5}Y+=b;ctx.fillStyle='#111b16aa';ctx.beginPath();ctx.ellipse(X+t*.5,Y+t*.82,t*.25,t*.1,0,0,7);ctx.fill();ctx.fillStyle=playerHitUntil>now?'#d66a58':'#283c32';ctx.fillRect(X+t*.3,Y+t*.48,t*.4,t*.36);ctx.fillStyle='#d5a06e';ctx.fillRect(X+t*.31,Y+t*.18,t*.38,t*.34);ctx.fillStyle='#3b2921';ctx.fillRect(X+t*.27,Y+t*.12,t*.46,t*.16);ctx.fillStyle='#171c19';ctx.fillRect(X+t*.4,Y+t*.3,3,3);ctx.fillRect(X+t*.59,Y+t*.3,3,3);if(swing||working){ctx.save();ctx.translate(X+t*.65,Y+t*.48);ctx.rotate(working?Math.sin(now/70)*.8:-1+swing*2);ctx.font=`${t*.45}px sans-serif`;ctx.fillText(working?(playerWorkType==='build'?'🔨':'⛏️'):weaponInfo().icon,0,0);ctx.restore()}}
function showWork(type,target,text){if(batchLeft)return;playerWorkType=type;playerWorkTarget=target;playerWorkUntil=performance.now()+650;addCombatFx(target.x,target.y,text,type==='build'?'#ffe09a':'#b9e79e')}
function showInvalidPlacement(x,y,reason){if(batchLeft)return;selected={x,y};invalidPlacement={x,y,until:performance.now()+1200};addCombatFx(x,y,'✕ 无法建造','#ff7868');toast(reason)}
function addCombatFx(x,y,text,color='#fff0a6'){if(batchLeft)return;combatFx.push({x,y,text,color,born:performance.now()})}
function drawCombatFx(){let now=performance.now();combatFx=combatFx.filter(f=>now-f.born<700);for(let f of combatFx){let age=(now-f.born)/700,[X,Y]=tileXY(f.x,f.y);ctx.globalAlpha=1-age;ctx.fillStyle=f.color;ctx.font=`bold ${Math.max(13,p.tile*.34)}px sans-serif`;ctx.textAlign='center';ctx.strokeStyle='#24130e';ctx.lineWidth=3;ctx.strokeText(f.text,X+p.tile*.5,Y+p.tile*(.25-age*.45));ctx.fillText(f.text,X+p.tile*.5,Y+p.tile*(.25-age*.45));ctx.globalAlpha=1}}
function itemAt(x,y){return objects.concat(drops).some(a=>a.x===x&&a.y===y)}
function occupied(x,y,animal=false){if(x<0||y<0||x>=COLS||y>=ROWS||map[y][x])return true;if(structures.some(a=>a.x===x&&a.y===y&&a.type!=='trap'&&!(a.type==='door'&&!animal)))return true;return !animal&&enemies.some(a=>a.x===x&&a.y===y)}
occupied=function(x,y,animal=false){if(x<0||y<0||x>=COLS||y>=ROWS)return true;let bridge=structures.some(a=>a.x===x&&a.y===y&&a.type==='bridge');if(map[y][x]&&!bridge&&(animal||!inv.boat))return true;if(structures.some(a=>a.x===x&&a.y===y&&!['trap','bridge'].includes(a.type)&&!(a.type==='door'&&!animal)))return true;return !animal&&enemies.some(a=>a.x===x&&a.y===y)};
function pathfind(tx,ty,animal=false,start={x:p.x,y:p.y}){let q=[start],seen=new Map([[`${start.x},${start.y}`,null]]),end;while(q.length){let a=q.shift();if(a.x===tx&&a.y===ty){end=a;break}for(let[dx,dy]of[[1,0],[-1,0],[0,1],[0,-1]]){let n={x:a.x+dx,y:a.y+dy},k=`${n.x},${n.y}`;if(!seen.has(k)&&(!occupied(n.x,n.y,animal)||(n.x===tx&&n.y===ty))){seen.set(k,a);q.push(n)}}}if(!end)return null;let out=[];while(end.x!==start.x||end.y!==start.y){out.unshift(end);end=seen.get(`${end.x},${end.y}`)}return out}
function nextTo(x,y){let best=[[1,0],[-1,0],[0,1],[0,-1]].map(([dx,dy])=>({x:x+dx,y:y+dy})).filter(a=>!occupied(a.x,a.y)).map(a=>({a,path:pathfind(a.x,a.y)})).filter(a=>a.path).sort((a,b)=>a.path.length-b.path.length)[0];if(best)p.path=best.path;else if(aiOn)logEvent(`AI跳过无法到达的目标 ${x},${y}`,'ai');else toast('无法靠近目标')}
function tap(e){if(!started||p.health<=0)return;let r=canvas.getBoundingClientRect(),x=Math.floor((e.clientX-r.left-p.ox)/p.tile+cameraX),y=Math.floor((e.clientY-r.top-p.oy)/p.tile);if(x<0||y<0||x>=COLS||y>=ROWS)return;selected={x,y};showDismantle(null);if(['trap','fence','door','kitchen','fridge','bed','shelter','strongShelter'].includes(mode)){place(x,y);return}let foe=enemies.find(a=>a.x===x&&a.y===y);if(foe){Math.abs(p.x-x)+Math.abs(p.y-y)===1?attack(foe):nextTo(x,y);return}let item=objects.concat(drops).find(a=>a.x===x&&a.y===y);if(item){Math.abs(p.x-x)+Math.abs(p.y-y)===1?pickupPrompt(item):nextTo(x,y);return}let build=structures.find(a=>a.x===x&&a.y===y);if(build&&Math.abs(p.x-x)+Math.abs(p.y-y)===1){if(build.type==='kitchen')kitchenPrompt(build);else if(build.type==='bed')bedPrompt(build);else if(['fence','door'].includes(build.type))fencePrompt(build);else buildingPrompt(build);return}hideAction();if(map[y][x]){if(inv.rod&&Math.abs(p.x-x)+Math.abs(p.y-y)===1)fish();else toast(inv.rod?'请先站到岸边':'水里不能走，需要鱼竿');return}let path=pathfind(x,y);if(path)p.path=path;else toast('那里过不去')}
function pickupPrompt(a){let g=growthInfo(a),growing=['wood','grass'].includes(a.type);$('#actionIcon').textContent=g.icon;$('#actionTitle').textContent=`采集${g.name}`;$('#actionText').textContent=a.type==='carcass'?'必须在厨房烹饪':growing?(g.next?`现在获得 ${g.yield} 份；继续生长会增产`:`已经成熟，可获得 ${g.yield} 份`):'收入背包';$('#actionButton').textContent='采集';$('#actionButton').disabled=false;$('#actionButton').onclick=()=>pickup(a);$('#actionPrompt').classList.remove('hidden')}
function pickup(a){let pool=objects.includes(a)?objects:drops,g=growthInfo(a),bonus=['wood','grass'].includes(a.type)?Math.floor(worldEra()/2)+(worldProfile.yieldBonus||0)+(dailyEvent==='丰收'?2:0):0,total=g.yield+bonus;showWork('gather',a,'采集中');pool.splice(pool.indexOf(a),1);inv[a.type]+=total;toast(`采集 ${g.icon} ${g.name}，获得${defs[a.type][0]} ×${total}${bonus?`（世界进程 +${bonus}）`:''}`);hideAction();updateUI();save()}
function kitchenPrompt(build){build=build||structures.find(a=>a.type==='kitchen');let n=inv.fish+inv.carcass,level=itemLevel('kitchen',build);$('#actionIcon').textContent='♨';$('#actionTitle').textContent=`野外厨房 · ${level}级`;$('#actionText').textContent=n?`可烹饪 ${n} 份食材；高等级厨房有熟食产量奖励`:'没有生鱼或动物肉';$('#actionButton').textContent='烹饪';$('#actionButton').disabled=!n;$('#actionButton').onclick=cook;showDismantle(build);$('#actionPrompt').classList.remove('hidden')}
function cook(){let n=inv.fish+inv.carcass;if(!n)return;let kitchen=structures.find(a=>a.type==='kitchen'),level=itemLevel('kitchen',kitchen),bonus=Math.floor(n*(level-1)*.15);inv.meal+=n+bonus;inv.fish=inv.carcass=0;toast(`${level}级厨房得到熟食 ×${n+bonus}${bonus?`（效率奖励 +${bonus}）`:''}`);kitchenPrompt();updateUI();save()}
function bedPrompt(build){let level=itemLevel('bed',build),heal=20+level*10;$('#actionIcon').textContent='🛏️';$('#actionTitle').textContent=`木床 · ${level}级`;$('#actionText').textContent=p.health>=100?'健康已经全满':`睡觉恢复 ${heal} 点健康；等级越高饥饿消耗越少`;$('#actionButton').textContent='睡觉';$('#actionButton').disabled=p.health>=100;$('#actionButton').onclick=sleep;showDismantle(build);$('#actionPrompt').classList.remove('hidden')}
function sleep(){let bed=structures.find(a=>a.type==='bed'&&Math.abs(a.x-p.x)+Math.abs(a.y-p.y)<=1),level=itemLevel('bed',bed),heal=20+level*10,hungerCost=Math.max(2,9-level);p.health=Math.min(100,p.health+heal);p.hunger=Math.max(0,p.hunger-hungerCost);toast(`${level}级床休息完成：健康 +${heal}，饥饿 -${hungerCost}`);hideAction();save()}
function wallName(wall,level=wall.level||1){let names=wall.type==='door'?['简易木门','加固木门','强化木门','铁箍木门','堡垒门']:['简易木栏','加固木栏','强化护栏','铁箍护栏','堡垒墙'];return names[Math.min(4,level-1)]}
function fencePrompt(wall){let level=itemLevel(wall.type,wall),cost=upgradeCost(wall.type,level);$('#actionIcon').textContent=wall.type==='door'?'▯':'▥';$('#actionTitle').textContent=`${wallName(wall)} · ${level}级`;$('#actionText').textContent=level>=5?`最高等级 · 耐久 ${Math.ceil(wall.hp)}/${wall.maxHp}`:`下一级需要木头 ${cost.wood}、草 ${cost.grass} · 当前耐久 ${Math.ceil(wall.hp)}/${wall.maxHp}`;$('#actionButton').textContent='保留';$('#actionButton').disabled=false;$('#actionButton').onclick=hideAction;showDismantle(wall);$('#actionPrompt').classList.remove('hidden')}
function upgradeWall(wall){upgradeItem(wall.type,wall)}
function spoilRawFood(){let fridge=structures.find(a=>a.type==='fridge'),capacity=fridge?itemLevel('fridge',fridge)*4:0,raw=inv.fish+inv.carcass;if(raw<=capacity)return;let lost=0;for(let type of ['fish','carcass'])if(inv[type]>0&&raw-lost>capacity){inv[type]--;lost++}if(lost)toast(`${fridge?`${itemLevel('fridge',fridge)}级冰箱容量 ${capacity}`:'没有木冰箱'}，${lost} 份生鲜腐坏了`)}
function showDismantle(build){let b=$('#dismantleButton');b.textContent='拆除';b.classList.add('danger');b.classList.toggle('hidden',!build);if(build)b.onclick=()=>dismantle(build);let u=$('#upgradeButton');u.classList.toggle('hidden',!build||!UPGRADEABLE.has(build.type));if(build&&UPGRADEABLE.has(build.type)){let level=itemLevel(build.type,build),cost=upgradeCost(build.type,level);u.textContent=level>=5?'已满级':`升级L${level+1} 🪵${cost.wood} 🌿${cost.grass}`;u.disabled=!canUpgrade(build.type,build);u.onclick=()=>upgradeItem(build.type,build);u.title=level>=5?'最高等级':`木头${cost.wood} 草${cost.grass}`}}
function buildingPrompt(build){$('#actionIcon').textContent=defs[build.type]?.[1]||'⌂';$('#actionTitle').textContent=`${defs[build.type]?.[0]||'建筑'} · ${itemLevel(build.type,build)}级`;$('#actionText').textContent='可以升级增强功能与耐久，也可以拆除后重新规划';$('#actionButton').textContent='保留';$('#actionButton').disabled=false;$('#actionButton').onclick=hideAction;showDismantle(build);$('#actionPrompt').classList.remove('hidden')}
const normalBuildingPrompt=buildingPrompt;
buildingPrompt=function(build){if(build.type!=='bridge')return normalBuildingPrompt(build);let missing=Math.max(0,(build.maxHp||100)-build.hp),cost=Math.max(1,Math.ceil(missing/25)),can=missing>0&&inv.wood>=cost;$('#actionIcon').textContent='🌉';$('#actionTitle').textContent='木桥维护';$('#actionText').textContent=missing?`耐久 ${Math.ceil(build.hp)}/${build.maxHp} · 使用木头 ${cost} 完全修复`:'耐久完好；涨潮期间会逐渐损耗';$('#actionButton').textContent=missing?'维修':'无需维修';$('#actionButton').disabled=!can;$('#actionButton').onclick=()=>{inv.wood-=cost;build.hp=build.maxHp;toast('木桥已经修复');hideAction();updateUI();save()};showDismantle(build);$('#actionPrompt').classList.remove('hidden')};
const bridgeBuildingPrompt=buildingPrompt;
function makeBerrySeeds(){if(!inv.berry)return;inv.berry--;let amount=Math.random()<.5?2:3;inv.seed+=amount;toast(`浆果没有吃掉，制成种子 ×${amount}`);updateUI();save()}
function farmAction(plot){if(!plot.plantedDay){if(!inv.seed)return;inv.seed--;plot.plantedDay=day;plot.watered=false;plot.readyDay=null;toast('已经播种，还需要用水壶浇水')}else if(!plot.watered){if(!inv.wateringCan)return;let days=Math.max(1,4-Math.floor(itemLevel('wateringCan')/2));plot.watered=true;plot.readyDay=day+days;toast(`${itemLevel('wateringCan')}级水壶浇水，预计第 ${plot.readyDay} 天成熟`)}else if(day>=plot.readyDay){let amount=2+itemLevel('farmPlot',plot)+Math.floor(Math.random()*4);inv.berry+=amount;plot.plantedDay=null;plot.watered=false;plot.readyDay=null;toast(`${itemLevel('farmPlot',plot)}级农田收获浆果 ×${amount}`)}updateUI();hideAction();save()}
buildingPrompt=function(build){if(build.type!=='farmPlot')return bridgeBuildingPrompt(build);let remaining=build.readyDay?Math.max(0,build.readyDay-day):null,action=!build.plantedDay?'播种':!build.watered?'浇水':remaining===0?'收获':'生长中',can=!build.plantedDay?!!inv.seed:!build.watered?!!inv.wateringCan:remaining===0;$('#actionIcon').textContent=remaining===0?'🫐':'🌱';$('#actionTitle').textContent='种植土壤';$('#actionText').textContent=!build.plantedDay?'消耗1颗种子':!build.watered?'需要水壶，浇水后3天成熟':remaining===0?'作物已经成熟':`距离收获还有 ${remaining} 天`;$('#actionButton').textContent=action;$('#actionButton').disabled=!can;$('#actionButton').onclick=()=>farmAction(build);showDismantle(build);$('#actionPrompt').classList.remove('hidden')};
function dismantle(build){let i=structures.indexOf(build);if(i<0)return;structures.splice(i,1);let recipe=recipes.find(r=>r.id===build.type);if(recipe)for(let[k,n]of Object.entries(recipe.cost))if(defs[k]&&!['spear','strongSpear'].includes(k))inv[k]+=Math.floor(n/2);toast(`拆除${defs[build.type]?.[0]||'建筑'}，返还部分材料`);hideAction();updateUI();save()}
function hideAction(){$('#actionPrompt').classList.add('hidden');showDismantle(null)}
function fish(){let level=itemLevel('rod'),delay=Math.max(300,1100-level*140);toast(`使用${level}级鱼竿抛线…`);setTimeout(()=>{let amount=1+(Math.random()<level*.12?1:0);inv.fish+=amount;toast(`钓到生鱼 ×${amount}，请带到厨房`);updateUI()},batchLeft?0:delay)}
function weaponInfo(){if(inv.hunterSpear){let l=itemLevel('hunterSpear');return{name:`猎兽矛 L${l}`,icon:'⚔️',damage:75+l*20,level:l}}if(inv.strongSpear){let l=itemLevel('strongSpear');return{name:`加固长矛 L${l}`,icon:'🔱',damage:50+l*15,level:l}}if(inv.spear){let l=itemLevel('spear');return{name:`木矛 L${l}`,icon:'🗡️',damage:25+l*15,level:l}}return{name:'徒手',icon:'✊',damage:15,level:0}}
function dropAnimalRemains(e,animal){let chance={boar:.62,wildDog:.18,wolf:.38,bear:.68,tiger:.52}[e.kind]??.4;if(Math.random()<chance){drops.push({x:e.x,y:e.y,type:'carcass',amount:animal.meat,bornDay:day});toast(`${animal.name}留下可食用生肉 ×${animal.meat}`)}else{drops.push({x:e.x,y:e.y,type:'bones',amount:1,bornDay:day});toast(`${animal.name}只剩下一具白骨，无法食用`)}}
function activeClothing(){let s=seasonInfo().name;if(s==='冬'||['严寒','寒风','降雪'].includes(weather))return'warmCoat';if(s==='夏'||weather==='炎热')return'coolClothes';return null}
function wearClothing(amount,reason){let type=activeClothing();if(!type||!inv[type])return;let level=itemLevel(type),max=100+(level-1)*25;clothingDurability[type]=Math.max(0,(clothingDurability[type]??max)-amount/Math.max(1,level*.65));if(!clothingDurability[type]){inv[type]--;clothingDurability[type]=max;toast(`${defs[type][0]}因${reason}彻底损坏，需要重新制作`)}}
function ageStoredClothing(){if(structures.some(a=>a.type==='storage'))return;for(let type of ['warmCoat','coolClothes'])if(inv[type]&&type!==activeClothing()){clothingDurability[type]=Math.max(0,(clothingDurability[type]??100)-1);if(!clothingDurability[type]){inv[type]--;clothingDurability[type]=100;toast(`${defs[type][0]}露天存放受潮损坏`)}}}
function attack(e){let animal=ANIMALS[e.kind]||ANIMALS.boar,weapon=weaponInfo();playerAttackUntil=performance.now()+260;playerAttackTarget={x:e.x,y:e.y};e.hp-=weapon.damage;e.hit=true;addCombatFx(e.x,e.y,`-${weapon.damage}`,'#ffe07b');setTimeout(()=>e.hit=false,180);toast(`${weapon.name}攻击${animal.name}，伤害 ${weapon.damage}`);if(e.hp<=0){runStats.kills++;enemies.splice(enemies.indexOf(e),1);dropAnimalRemains(e,animal)}}
function confirmPlacement(type,x,y,commit){if(batchLeft)return commit();pendingPlacement={type,x,y};selected={x,y};$('#actionIcon').textContent=defs[type]?.[1]||'🔨';$('#actionTitle').textContent=`确认建造${defs[type]?.[0]||type}`;$('#actionText').textContent=`确定放在第 ${x+1} 列、第 ${y+1} 行吗？确认后才会消耗建筑物品。`;$('#actionButton').textContent=aiOn?'AI 正在确认…':'确认建造';$('#actionButton').disabled=!!aiOn;$('#actionButton').onclick=()=>{pendingPlacement=null;hideAction();if(started&&p.health>0)commit()};let cancel=$('#dismantleButton');cancel.textContent='换个位置';cancel.classList.remove('danger');cancel.classList.toggle('hidden',!!aiOn);cancel.onclick=()=>{pendingPlacement=null;hideAction()};$('#actionPrompt').classList.remove('hidden');if(aiOn){aiPresentationUntil=performance.now()+500;setTimeout(()=>{if(pendingPlacement?.type===type&&pendingPlacement.x===x&&pendingPlacement.y===y){pendingPlacement=null;hideAction();if(started&&p.health>0)commit()}},500)}}
function commitPlace(type,x,y,bridge){if(!inv[type])return setMode('hand');let level=itemLevels[type]||1,durability={trap:1,fence:80,door:80,kitchen:60,fridge:50,bed:45,shelter:80,strongShelter:160,farmPlot:50,storage:70}[type]||40,durabilityScaled=Math.round(durability*(1+(level-1)*.65)),building={x,y,type,level,hp:durabilityScaled,maxHp:durabilityScaled,bridgeFoundation:!!bridge};if(type==='trap')building.charges=level;structures.push(building);inv[type]--;showWork('build',{x,y},'建造中');let protection=houseProtection();toast(protection?`房屋已封闭！抵挡动物，天气防护 ${protection}`:`已放置${level}级${defs[type][0]}${bridge?'（桥面地基）':''}`);setMode('hand');updateUI();save()}
function place(x,y){let type=mode;if(!inv[type])return setMode('hand');let tidal=TIDAL_CELLS.some(a=>a.x===x&&a.y===y),bridge=structures.find(a=>a.x===x&&a.y===y&&a.type==='bridge'),blocked=structures.some(a=>a.x===x&&a.y===y&&a.type!=='bridge');if(tidal&&!bridge)return showInvalidPlacement(x,y,'洪泛浅滩必须先铺木桥，建筑才能以桥面为地基');if(occupied(x,y)||itemAt(x,y)||blocked||p.x===x&&p.y===y)return showInvalidPlacement(x,y,'这里不能建造');confirmPlacement(type,x,y,()=>commitPlace(type,x,y,bridge))}
function houseInterior(x,y){if(map[y]?.[x])return false;let q=[{x,y}],seen=new Set([`${x},${y}`]),walls=0;while(q.length){let a=q.shift();for(let[dx,dy]of[[1,0],[-1,0],[0,1],[0,-1]]){let nx=a.x+dx,ny=a.y+dy;if(nx<0||ny<0||nx>=COLS||ny>=ROWS||map[ny][nx])return false;if(structures.some(s=>s.x===nx&&s.y===ny&&['fence','door'].includes(s.type))){walls++;continue}let k=`${nx},${ny}`;if(!seen.has(k)){seen.add(k);q.push({x:nx,y:ny});if(seen.size>40)return false}}}return walls>=4&&structures.some(s=>s.type==='door')}
function spawnEnemy(){let season=seasonInfo(),spots=[];for(let y=1;y<ROWS-1;y++)for(let x=1;x<COLS-1;x++)if(!occupied(x,y,true)&&!itemAt(x,y)&&!houseInterior(x,y)&&Math.abs(x-p.x)+Math.abs(y-p.y)>5)spots.push({x,y});let maxEnemies=Math.min(9,3+worldEra()+Math.floor(day/5));if(!spots.length||enemies.length>=maxEnemies||Math.random()>Math.min(1,worldProfile.enemy+(dailyEvent==='兽潮'?.25:0)))return;let pool=Object.entries(ANIMALS).filter(([,a])=>day>=a.unlock&&a.seasons.includes(season.name)).sort((a,b)=>a[1].tier-b[1].tier);if(!pool.length)return;let chosen=Math.random()<Math.min(.85,.55+worldEra()*.05)?pool[pool.length-1]:pool[Math.floor(Math.random()*pool.length)],kind=chosen[0],animal=chosen[1],spot=spots[Math.floor(Math.random()*spots.length)],hp=Math.round((animal.hp+Math.floor((day-animal.unlock)/7)*12)*worldProfile.enemy);enemies.push({...spot,kind,hp,maxHp:hp,lastMove:time,lastAttack:0,hit:false});toast(`${animal.tier>=4?'🚨':'⚠'} ${animal.rank}·${animal.name}出现！${hp} 生命 / 攻击 ${animal.damage}`)}
function spawnResources(count=1){const MAX=20+worldEra()*2,season=seasonInfo(),rates=season.resources;if(objects.length>=MAX||Math.random()>Math.min(1,worldProfile.resource+(dailyEvent==='丰收'?.2:0)))return 0;let empty=[];for(let y=1;y<ROWS-1;y++)for(let x=1;x<COLS-1;x++)if(!map[y][x]&&!occupied(x,y)&&!itemAt(x,y)&&!houseInterior(x,y)&&!(p.x===x&&p.y===y))empty.push({x,y});let added=0;while(count--&&empty.length&&objects.length<MAX){let i=Math.floor(Math.random()*empty.length),spot=empty.splice(i,1)[0],roll=Math.random(),type=roll<rates[0]?'wood':roll<rates[0]+rates[1]?'grass':'berry';objects.push({...spot,type,born:time});added++}if(added)save();return added}
function houseProtection(){let q=[{x:p.x,y:p.y}],seen=new Set([`${p.x},${p.y}`]),boundary=[];while(q.length){let a=q.shift();for(let[dx,dy]of[[1,0],[-1,0],[0,1],[0,-1]]){let x=a.x+dx,y=a.y+dy;if(x<0||y<0||x>=COLS||y>=ROWS||map[y][x])return 0;let wall=structures.find(s=>s.x===x&&s.y===y&&['fence','door'].includes(s.type));if(wall){boundary.push(wall);continue}let k=`${x},${y}`;if(!seen.has(k)){seen.add(k);q.push({x,y});if(seen.size>40)return 0}}}return boundary.some(s=>s.type==='door')&&boundary.length>=4?Math.min(...boundary.map(s=>s.level||1)):0}
function enclosedByFence(){return houseProtection()>0}
function weatherProtection(){let strength=houseProtection();for(let a of structures.filter(a=>['shelter','strongShelter'].includes(a.type)&&Math.abs(a.x-p.x)+Math.abs(a.y-p.y)<=1))strength=Math.max(strength,itemLevel(a.type,a)+(a.type==='strongShelter'?1:0));return strength}
function enemyAI(){for(let e of [...enemies]){if(time-e.lastMove<750)continue;e.lastMove=time;let animal=ANIMALS[e.kind]||ANIMALS.boar,d=Math.abs(e.x-p.x)+Math.abs(e.y-p.y);if(d===1){if(time-e.lastAttack>1200){let hit=animal.damage+Math.floor((day-animal.unlock)/4)*2;e.lastAttack=time;p.health=Math.max(0,p.health-hit);wearClothing(5,'动物撕咬');runStats.damage.enemy+=hit;runStats.lastDamageSource='enemy';toast(`${animal.name}攻击！健康 -${hit}`)}continue}let path=pathfind(p.x,p.y,true,{x:e.x,y:e.y});if(!path?.length){let targets=structures.filter(s=>s.type!=='trap').map(s=>({s,path:pathfind(s.x,s.y,true,{x:e.x,y:e.y})})).filter(a=>a.path?.length).sort((a,b)=>a.path.length-b.path.length),target=targets[0];if(!target)continue;if(target.path.length===1){let building=target.s;building.maxHp=building.maxHp||(['fence','door'].includes(building.type)?80:60);building.hp=(building.hp??building.maxHp)-animal.damage;toast(`${animal.name}攻击${defs[building.type][0]}，耐久 -${animal.damage}`);if(building.hp<=0){structures.splice(structures.indexOf(building),1);toast(`${defs[building.type][0]}被摧毁！`)}continue}path=target.path}let n=path[0];if(n.x===p.x&&n.y===p.y)continue;e.x=n.x;e.y=n.y;let trap=structures.find(a=>a.x===e.x&&a.y===e.y&&a.type==='trap');if(trap){let level=itemLevel('trap',trap),damage=35+level*20;trap.charges=(trap.charges||level)-1;if(trap.charges<=0)structures.splice(structures.indexOf(trap),1);e.hp-=damage;toast(`${level}级陷阱命中${animal.name}，生命 -${damage}，剩余次数 ${Math.max(0,trap.charges)}！`);if(e.hp<=0){runStats.kills++;enemies.splice(enemies.indexOf(e),1);dropAnimalRemains(e,animal)}}}}
function clothingProtection(){let type=activeClothing();return type?(inv[type]&&clothingDurability[type]>0?itemLevel(type):0):1}
function simulateStep(dt){if(!started||p.health<=0)return;time+=dt;p.hunger=Math.max(0,p.hunger-dt*.00055);if(p.hunger<=0){p.hunger=0;runStats.lastDamageSource='hunger';runStats.minHunger=0;updateStats();return}let d=Math.floor(time/60000)+1;if(d!==day){let oldSeason=seasonInfo().name;day=d;let season=seasonInfo();weather=season.weather[Math.floor(Math.random()*season.weather.length)][0];let grown=spawnResources(4);toast(`${season.name} · 第 ${day} 天：${weather}，新生物资 ${grown} 份${oldSeason!==season.name?'，新季节开始':''}`)}resourceClock+=dt;while(resourceClock>=8000){resourceClock-=8000;spawnResources(1)}let severity=weatherInfo()[1],weatherDamage=Math.max(0,severity-weatherProtection()),clothingDamage=clothingProtection()?0:1,damage=weatherDamage+clothingDamage;if(damage){weatherClock+=dt;while(weatherClock>=2500){weatherClock-=2500;p.health=Math.max(0,p.health-damage);runStats.damage.weather+=damage;runStats.lastDamageSource='weather';toast(`${weather}与${seasonInfo().name}季环境伤害 ${damage}（建筑防护 ${weatherProtection()}，衣物 ${clothingProtection()?'合适':'不合适'}）`)}}else weatherClock=0;enemyClock+=dt;while(enemyClock>=12000){enemyClock-=12000;if(Math.random()<.75)spawnEnemy()}aiClock+=dt;while(aiOn&&aiClock>=650){aiClock-=650;aiStep()}enemyAI();if(p.path.length){let n=p.path[0],speed=dt*.006,dist=Math.hypot(n.x-p.px,n.y-p.py);if(dist<=speed){p.px=p.x=n.x;p.py=p.y=n.y;p.path.shift()}else{p.px+=(n.x-p.px)/dist*speed;p.py+=(n.y-p.py)/dist*speed}}runStats.minHealth=Math.min(runStats.minHealth,p.health);runStats.minHunger=Math.min(runStats.minHunger,p.hunger);updateStats()}
const baseSimulateStep=simulateStep;
function floodUnprotectedTiles(){let tidal=new Set(TIDAL_CELLS.map(a=>`${a.x},${a.y}`)),bridged=new Set(structures.filter(a=>a.type==='bridge').map(a=>`${a.x},${a.y}`)),lostBuildings=structures.filter(a=>a.type!=='bridge'&&tidal.has(`${a.x},${a.y}`)&&!bridged.has(`${a.x},${a.y}`));for(let a of lostBuildings)structures.splice(structures.indexOf(a),1);let before=objects.length+drops.length;objects=objects.filter(a=>!tidal.has(`${a.x},${a.y}`)||bridged.has(`${a.x},${a.y}`));drops=drops.filter(a=>!tidal.has(`${a.x},${a.y}`)||bridged.has(`${a.x},${a.y}`));let lostItems=before-objects.length-drops.length;if(lostBuildings.length||lostItems)toast(`洪水摧毁：未架桥建筑 ${lostBuildings.length} 座，地面物资 ${lostItems} 份`)}
function damageBridgesForDay(){if(tide!=='涨潮'||lastBridgeDamageDay===day)return;lastBridgeDamageDay=day;let collapsed=[];for(let bridge of structures.filter(a=>a.type==='bridge')){bridge.hp-=Math.max(5,17-itemLevel('bridge',bridge)*2);if(bridge.hp<=0)collapsed.push({x:bridge.x,y:bridge.y})}if(collapsed.length){let keys=new Set(collapsed.map(a=>`${a.x},${a.y}`));structures=structures.filter(a=>!keys.has(`${a.x},${a.y}`));objects=objects.filter(a=>!keys.has(`${a.x},${a.y}`));drops=drops.filter(a=>!keys.has(`${a.x},${a.y}`));toast(`${collapsed.length} 座失修木桥连同桥面建筑和物资被冲垮！`)}else if(structures.some(a=>a.type==='bridge'))toast('涨潮日结算：桥梁按等级损耗耐久')}
function updateTide(){let weekDay=(day-1)%7+1,next=weekDay===5||weekDay===6?'涨潮':'退潮';if(next!==tide){tide=next;for(let a of TIDAL_CELLS)map[a.y][a.x]=tide==='涨潮'?1:BASE_TERRAIN[a.y][a.x];p.path=[];if(tide==='涨潮'){floodUnprotectedTiles();toast('🌊 周期涨潮！第5—6天浅滩被淹；无桥建筑和物资会被摧毁')}else toast('🏝 第7天退潮！沿岸浅滩重新露出')}damageBridgesForDay()}
function strandedByTide(){return !!map[p.y]?.[p.x]&&!inv.boat&&!structureAt(p.x,p.y,'bridge')}
simulateStep=function(dt){let previousTime=time,heldAI=aiOn;if(strandedByTide()){p.path=[];aiOn=false}baseSimulateStep(dt);aiOn=heldAI;if(!started)return;updateTide();if(Math.floor(previousTime/12000)!==Math.floor(time/12000))spawnResources(1)};
function animate(now){let elapsed=Math.min(100,now-last);last=now;if(!paused||batchLeft)simAccumulator+=elapsed*(batchLeft?BATCH_SPEED:1);let steps=0,maxSteps=batchLeft?800:200;while(simAccumulator>=SIM_STEP&&steps<maxSteps){simulateStep(SIM_STEP);simAccumulator-=SIM_STEP;steps++}if(!batchLeft)draw();requestAnimationFrame(animate)}
function rollDailyEvent(){let events=['平静','平静','丰收','兽潮','灾害预警'];dailyEvent=events[Math.floor(Math.random()*events.length)];logEvent(`今日世界事件：${dailyEvent}`,'info')}
function gameSnapshot(){return JSON.parse(JSON.stringify({day,time,weather,dailyEvent,worldProfile,objects,structures,enemies,drops,inv,itemLevels,clothingDurability,p:{x:p.x,y:p.y,px:p.x,py:p.y,health:p.health,hunger:p.hunger},runStats}))}
function saveCheckpoint(){if(batchLeft||(day!==1&&(day-1)%3!==0))return;let list=JSON.parse(localStorage.getItem('island-checkpoints-v1')||'[]').filter(s=>s.day!==day);list.push(gameSnapshot());localStorage.setItem('island-checkpoints-v1',JSON.stringify(list.slice(-3)))}
function checkpointCount(){return JSON.parse(localStorage.getItem('island-checkpoints-v1')||'[]').length}
function restoreCheckpoint(){let list=JSON.parse(localStorage.getItem('island-checkpoints-v1')||'[]');if(!list.length)return restartGame();let s=list[list.length-1];objects=s.objects||[];structures=s.structures||[];enemies=s.enemies||[];drops=s.drops||[];inv={...Object.fromEntries(Object.keys(defs).map(k=>[k,0])),...s.inv};itemLevels=s.itemLevels||{};clothingDurability=s.clothingDurability||{warmCoat:100,coolClothes:100};worldProfile=s.worldProfile||randomWorldProfile();dailyEvent=s.dailyEvent||'平静';time=s.time;day=lastSpoilDay=s.day;weather=s.weather;p={...p,...s.p,path:[],tile:p.tile,ox:p.ox,oy:p.oy};runStats=s.runStats||{kills:0,meals:0,damage:{enemy:0,weather:0,hunger:0},lastDamageSource:null,minHealth:p.health,minHunger:p.hunger};enemyClock=weatherClock=aiClock=resourceClock=0;runEnding=false;started=true;aiOn=false;localStorage.setItem('island-checkpoints-v1',JSON.stringify([s]));$('#welcome').classList.add('closed');$('#welcome').classList.remove('gameover');$('#restartButton').classList.add('hidden');$('#clearGameButton').classList.add('hidden');updateAIButton();updateUI();save();toast(`已回到第 ${day} 天的安全存档`)}
function updateBatchProgress(force=false){if(!batchLeft||!force)return;let runs=evolution?.config.runs||10,completed=runs-batchLeft,current=completed+1;if(evolution){let done=(evolution.generation-1)*evolution.population.length*runs+evolution.candidate*runs+completed,total=evolution.maxGenerations*evolution.population.length*runs;$('#batchProgressText').textContent=`第 ${evolution.generation} / ${evolution.maxGenerations} 代 · 权重个体 ${evolution.candidate+1} / ${evolution.population.length} · 正在跑第 ${current} / ${runs} 局`;$('#batchProgressExplain').textContent=evolution.lastDirection||(evolution.generation===1?(evolution.coldStart?'首次学习：随机探索全部行为权重':'继续学习：冠军保留 + 扩大范围变异'):'自然选择：保留冠军，交叉并变异其余个体');$('#batchProgressBar').style.width=`${done/total*100}%`}else{$('#batchProgressText').textContent=`当前策略 · 正在跑第 ${current} / 10 局`;$('#batchProgressExplain').textContent='固定策略基准测试，每局结束后追加结果';$('#batchProgressBar').style.width=`${completed*10}%`}}
function appendBatchResult(record){if(!batchLeft)return;let runs=evolution?.config.runs||10,index=runs-batchLeft+1,names={enemy:'动物',weather:'天气',hunger:'饥饿',survived:'通过'},list=$('#batchRunResults'),prefix=evolution?`第 ${evolution.generation} 代 · 个体 ${evolution.candidate+1} · `:'',quality=record.day>=7?'good':record.day<=4?'bad':'';list.insertAdjacentHTML('beforeend',`<p><span>${prefix}第 ${index} 局</span><span class="${quality}"><b>${record.day} 天</b> · ${names[record.cause]||record.cause}</span></p>`);list.scrollTop=list.scrollHeight;let completed=evolution?(evolution.generation-1)*evolution.population.length*runs+evolution.candidate*runs+index:index,total=evolution?evolution.maxGenerations*evolution.population.length*runs:10;$('#batchProgressBar').style.width=`${completed/total*100}%`}
function updateWeatherUI(){let severity=weatherInfo()[1],snow=['降雪','严寒','寒风'].includes(weather),storm=['暴雨','雷雨','大风'].includes(weather),heat=weather==='炎热';document.body.classList.toggle('weather-snow',snow);document.body.classList.toggle('weather-storm',storm);document.body.classList.toggle('weather-heat',heat);let alert=$('#weatherAlert');alert.classList.toggle('hidden',!severity);if(severity){alert.querySelector('b').textContent=`${weather} · 强度 ${severity}`;alert.querySelector('small').textContent=weatherProtection()>=severity?'当前建筑防护充足':`防护 ${weatherProtection()}，立即进入房屋或庇护所`}}
function updateStats(){if(day>lastSpoilDay){lastSpoilDay=day;rollDailyEvent();spoilRawFood();wearClothing(Math.max(2,weatherInfo()[1]*4),'天气磨损');ageStoredClothing();drops=drops.filter(a=>a.type!=='bones'||day-(a.bornDay||day)<2);saveCheckpoint();if(!batchLeft)updateUI()}if((p.health<=0||p.hunger<=0)&&!runEnding)finishRun(false);if(batchLeft){updateBatchProgress();return}$('#healthBar').style.width=p.health+'%';$('#healthText').textContent=Math.ceil(p.health);$('#hungerBar').style.width=p.hunger+'%';$('#hungerText').textContent=Math.ceil(p.hunger);$('#dayLabel').textContent=`${seasonInfo().name} · 第 ${day} 天 · ${weather} · ${tide}`;updateWeatherUI()}
function inventoryGroup(title,keys,note=''){let filled=keys.filter(k=>inv[k]);return `<h3 style="font-size:10px;color:#d6bd7c;margin:10px 0 6px">${title}</h3><div class="inventory">${filled.length?filled.map(k=>`<div class="item"><em>${inv[k]}</em><div class="item-icon">${defs[k][1]}</div><b>${defs[k][0]}</b>${['berry','meal'].includes(k)?`<button data-eat="${k}"></button>`:''}</div>`).join(''):'<div class="item empty">暂无</div>'}</div>${note?`<p style="color:#89988e;font-size:9px">${note}</p>`:''}`}
function craftGroup(title,cat){let list=recipes.filter(r=>r.cat===cat);return `<section class="craft-group"><h3>${title}</h3>${list.map(r=>{let unlocked=(!r.unlock||day>=r.unlock)&&(!r.requires||inv[r.requires]),can=unlocked&&Object.entries(r.cost).every(([k,n])=>inv[k]>=n),lockText=r.requires&&!inv[r.requires]?`需要${defs[r.requires][0]}`:`第${r.unlock}天解锁`;return `<div class="craft-card"><div class="craft-icon">${defs[r.id][1]}</div><div><h3>${r.name}${unlocked?'':` · ${lockText}`}</h3><p>${r.desc}</p><div class="cost">${Object.entries(r.cost).map(([k,n])=>`<span class="${inv[k]>=n?'ok':''}">${defs[k][1]} ${inv[k]}/${n}</span>`).join('　')}</div></div><button data-craft="${r.id}" ${can?'':'disabled'}>${unlocked?'制作':'未解锁'}</button></div>`}).join('')}</section>`}
